// Each bit position is a counter mod 3, stored across two registers:
//   (ones, twos) = (0,0) -> seen 0 times, (1,0) -> once, (0,1) -> twice.
// A third occurrence must return the pair to (0,0).
int singleNumberII(const vector<int>& a) {
    int ones = 0, twos = 0;
    for (int x : a) {
        ones = (ones ^ x) & ~twos;   // add x to ones, but clear where twos holds it
        twos = (twos ^ x) & ~ones;   // add x to twos, but clear where ones now holds it
    }
    return ones;                      // the element seen exactly once
}

// GENERAL k: count set bits per column mod k. Works for any k, costs O(32n).
int singleNumberModK(const vector<int>& a, int k) {
    int result = 0;
    for (int bit = 0; bit < 32; ++bit) {
        int count = 0;
        for (int x : a) count += ((unsigned int)x >> bit) & 1;
        if (count % k) result |= (1 << bit);   // this column belongs to the loner
    }
    return result;
}

int getSum(int a, int b) {
    // Work in UNSIGNED: signed overflow during carry propagation is UB in C++.
    unsigned int x = (unsigned int)a, y = (unsigned int)b;
    while (y) {
        unsigned int carry = (x & y) << 1;   // where BOTH have a 1, carry left
        x = x ^ y;                            // sum ignoring carries
        y = carry;                            // fold the carry back in
    }
    return (int)x;
}
// TRACE -7 + 3 in 8-bit for readability (-7 is 11111001, 3 is 00000011):
//   x^y = 11111010,  carry = (11111001 & 00000011) << 1 = 00000010
//   x = 11111010, y = 00000010
//   x^y = 11111000,  carry = (11111010 & 00000010) << 1 = 00000100
//   x = 11111000, y = 00000100
//   x^y = 11111100,  carry = 00000000  -> done, x = 11111100 = -4. Correct.

int divide(int dividend, int divisor) {
    // THE ONLY OVERFLOW CASE: INT_MIN / -1 is 2147483648, which does not fit.
    if (dividend == INT_MIN && divisor == -1) return INT_MAX;

    bool negative = (dividend < 0) != (divisor < 0);      // sign extracted FIRST
    // Use unsigned absolutes: -INT_MIN overflows a signed int.
    unsigned int a = dividend < 0 ? -(unsigned int)dividend : dividend;
    unsigned int b = divisor  < 0 ? -(unsigned int)divisor  : divisor;

    unsigned int quotient = 0;
    for (int shift = 31; shift >= 0; --shift) {
        // if b fits into the remaining dividend when scaled by 2^shift, take it
        if ((a >> shift) >= b) {
            a -= (b << shift);
            quotient |= (1u << shift);
        }
    }
    return negative ? -(int)quotient : (int)quotient;
}

// LOOP: pull bits off the bottom, push them onto the top.
unsigned int reverseBitsLoop(unsigned int n) {
    unsigned int out = 0;
    for (int i = 0; i < 32; ++i) {
        out = (out << 1) | (n & 1);
        n >>= 1;
    }
    return out;
}

// BUTTERFLY: swap adjacent blocks of size 1, then 2, 4, 8, 16.
// Read the hex masks as block patterns:
//   0x55555555 = 0101...  (odd/even single bits)
//   0x33333333 = 0011...  (pairs)
//   0x0F0F0F0F = 00001111 (nibbles)
//   0x00FF00FF            (bytes)
unsigned int reverseBitsButterfly(unsigned int n) {
    n = ((n >> 1)  & 0x55555555u) | ((n & 0x55555555u) << 1);
    n = ((n >> 2)  & 0x33333333u) | ((n & 0x33333333u) << 2);
    n = ((n >> 4)  & 0x0F0F0F0Fu) | ((n & 0x0F0F0F0Fu) << 4);
    n = ((n >> 8)  & 0x00FF00FFu) | ((n & 0x00FF00FFu) << 8);
    n = (n >> 16) | (n << 16);
    return n;
}
// CYCLES: the loop is 32 dependent iterations; the butterfly is 5 independent
// rounds of three operations each. On a modern CPU the butterfly is roughly
// 5-10x faster, and it has no branches at all.

int rangeBitwiseAnd(int m, int n) {
    int shifts = 0;
    while (m < n) { m >>= 1; n >>= 1; ++shifts; }   // strip differing low bits
    return m << shifts;                              // restore with zeros below
}
// WHY: if m < n then somewhere in the range a bit flips from 0 to 1, and every
// bit below the highest differing position takes BOTH values across the range --
// so each of those columns contains at least one 0 and ANDs to 0. Only the
// shared high prefix survives.
// BRUTE FORCE dies because the range can span 2^31 values; looping over it is
// billions of iterations for a result determined by ~31 shifts.

vector<vector<int>> subsetsMask(const vector<int>& a) {
    int n = (int)a.size();
    vector<vector<int>> out;
    out.reserve(1u << n);
    for (unsigned int mask = 0; mask < (1u << n); ++mask) {
        vector<int> cur;
        for (int j = 0; j < n; ++j)
            if (mask & (1u << j)) cur.push_back(a[j]);
        out.push_back(move(cur));
    }
    return out;
}
// ORDER DIFFERS from the recursive pick/not-pick version: masks ascend
// numerically, so [] comes first, then [a0], [a1], [a0,a1], ... The SET of
// subsets is identical; the sequence is not. Never assume they match.
